import sys

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N)]

    last = {}
    INF = N + 5
    ans = INF

    for idx, val in enumerate(A):
        if val in last:
            length = idx - last[val] + 1
            if length < ans:
                ans = length
        last[val] = idx

    if ans == INF:
        print(-1)
    else:
        print(ans)

if __name__ == "__main__":
    solve()
```
